"""Preserve bcrypt credentials when upgrading the hashing implementation."""

import pytest

from api.auth import hash_password, verify_password
from api.services.tenants import pwd_context as tenant_context


@pytest.mark.parametrize("prefix", ["2a", "2b", "2y"])
def test_legacy_passlib_hash_still_verifies(prefix):
    # Generated by passlib 1.7.4 with the unchanged default cost of 12.
    legacy = '$2b$12$V0qAwfVX34d35OeZyQi9pepbxgvKRPq//k.jQeTWpgrdLwWKUI1fq'
    legacy = "$" + prefix + legacy[3:]
    assert verify_password("legacy-warning-regression", legacy)
    assert not verify_password("wrong-password", legacy)
    assert tenant_context.verify("legacy-warning-regression", legacy)


def test_new_hash_retains_bcrypt_cost_and_verifies():
    hashed = hash_password("new-warning-regression")
    assert hashed.startswith("$2b$12$")
    assert verify_password("new-warning-regression", hashed)
    assert tenant_context.verify("new-warning-regression", hashed)
